import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.1.1/src/p5.flex.min.mjs"
/* [Inlined Multi-Tab] shader.js */

mountFlex(p5)

function forcesOfParticle([x,y,z]){
	var distance = Math.sqrt(x*x + y*y + z*z);
	if(distance < 0.01){
		return [0,0,0];
	}
	var fx = - x / distance;
	var fy = - y / distance;
	var fz = - z / distance;
	return [fx,fy,fz];
}

new p5((p) => {
	const [WIDTH, HEIGHT] = [600, 600]
	const PIXEL_DENSITY = 2
	const CANVAS_SIZE = [WIDTH, HEIGHT]
	let theShader
	let [x,y,z] = [0.1,0.3,0.4]
	let [vx,vy,vz] = [0.8,0,0]

	p.setup = () => {
		p.createCanvas(WIDTH, HEIGHT, p.WEBGL)
		p.flex({ container: { padding: "20px" }, canvas: { fit: p.SCALE_DOWN } })

		p.pixelDensity(PIXEL_DENSITY)

		theShader = p.createShader(vert, frag)

		p.noStroke()
		p.imageMode(p.CENTER)
	}

	p.draw = () => {
		let [fx,fy,fz] = forcesOfParticle([x,y,z])
		let coef = 0.001;
		let coef2 = Math.random()*2.4;
		vx += coef * (fx + coef2 * Math.random())
		vy += coef * (fy + coef2 * Math.random())
		vz += coef * (fz + coef2 * Math.random())

		x += vx
		y += vy
		z += vz

		vx *= 0.98
		vy *= 0.98
		vz *= 0.98

		p.background(255)
		p.shader(theShader)
		theShader.setUniform("canvasSize", CANVAS_SIZE)
		theShader.setUniform("a", x+0.5)
		theShader.setUniform("b", y+0.5)
		theShader.setUniform("c", z+0.5)
		p.quad(-1, 1, 1, 1, 1, -1, -1, -1)
	}
})



// === Tab: shader.js ===

// noprotect

// https://github.com/ZRNOF/Shox
import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.0.0/src/Shox.js"

const frag = `#version 300 es
  precision mediump float;

  uniform vec2 canvasSize;
	uniform float a;
  uniform float b;
  uniform float c;

  ${Shox.displace}
  ${Shox.noiseMath}
  ${Shox.snoise3D}
  ${Shox.snoise3DImage}
  ${Shox.gradient}
  ${Shox.zcPalette(5)}
  ${Shox.extend}
  ${Shox.smooth}

  in vec2 vTexCoord;
  out vec4 fragColor;
  void main() {
    vec2 uv = vTexCoord;
    vec2 mo = vec2(a,b);
    mo = min(max(vec2(0.), mo), vec2(1.));

    uv-=0.5;
    uv.x *= canvasSize.x/canvasSize.y;

    vec2 muv = smoo3(mirror(uv, 1.));

    float scal = 2.;
    float gain = mo.y*100.;
    float ofst = .5*mo.x;
    float expo = mo.x*2.5;
    vec3  move = vec3(a, b, c);
    vec4 dimg = snoise3DImage(1.*uv, scal, gain, ofst, expo, move);

    float wei = 0.1*c*a;
    vec2 duv = smoo3(displace(muv, dimg.rg, ofst, wei));

    vec2 puv = smoo3(conical(duv, vec2(.2), 5., c));

    vec4 colors[] = vec4[](
      vec4(a, 0.18, 0.019, 1.0), 
      vec4(0.14, a, 0.2, 1.0),
      vec4(1.0, c,b, 1.0),
			vec4(a, c, 0.0, 1.0),
      vec4(0.086, 0.18, c, 1.0)

			//vec4(0.0, 0.0, 0.0, 1.0): Black (RGB: 0, 0, 0) with full opacity (Alpha: 1.0)
	//vec4(0.8, 0.5, 0.0, 1.0): An orange-ish color (RGB: 0.8, 0.5, 0.0) with full opacity (Alpha: 1.0)
	//vec4(1.0, 1.0, 1.0, 1.0): White (RGB: 1.0, 1.0, 1.0) with full opacity (Alpha: 1.0)
	//vec4(0.3, 0.6, 0.7, 1.0): A light blue color (RGB: 0.3, 0.6, 0.7) with full opacity (Alpha: 1.0)
	//vec4(0.0, 0.0, 0.0, 1.0): Again, black with full opacity
    );
    float positions[] = float[](
      0.0,
      0.25,
      0.5,
      0.75,
      1.0
    );
    vec4 color = smoo3(palette(puv.x, colors, positions));

    fragColor = smoo3(color);
  }
`

const vert = `#version 300 es

  in vec4 aPosition;
  in vec2 aTexCoord;

  out vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    gl_Position = aPosition;
  }
`

